import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { AlertsButton } from '@/components/AlertsButton'
import { DecisionList, visibleOrder } from '@/components/DecisionList'
import { DecisionPane, type Offer } from '@/components/DecisionPane'
import { EvidenceDrawer, type DrawerView } from '@/components/EvidenceDrawer'
import { LaunchTimeline } from '@/components/LaunchTimeline'
import { Routines, RoutinesLive } from '@/components/Routines'
import { pendingOf, useLive } from '@/components/routines/live'
import { MapLegend, SupplierList, SupplyMap, type MapSelection } from '@/components/SupplyMap'
import { Today, type DoneInfo } from '@/components/Today'
import { TopBar, type Page } from '@/components/TopBar'
import { DECIDED, DONE_WORD, fetchState, tidy, viaOf, type Card, type State } from '@/lib/api'
import { actionIdOf, groupKey, sections } from '@/lib/decisions'
import { lookAlikes, todayOrder, trucksLeave } from '@/lib/today'

const POLL_MS = 5000

function useMedia(q: string) {
  const [on, setOn] = useState(() => window.matchMedia(q).matches)
  useEffect(() => {
    const m = window.matchMedia(q)
    const f = () => setOn(m.matches)
    m.addEventListener('change', f)
    return () => m.removeEventListener('change', f)
  }, [q])
  return on
}

export default function App() {
  const [state, setState] = useState<State | null>(null)
  const [error, setError] = useState(false)
  const [nowMs, setNowMs] = useState(Date.now())
  const [path, setPath] = useState(window.location.pathname)
  const [toast, setToast] = useState<string | null>(null)
  const [pulseNode, setPulseNode] = useState<string | null>(null)
  const [drafts, setDrafts] = useState(0)
  // Today: the decision in focus, and the "Done" screen after one.
  const [focusId, setFocusId] = useState<string | null>(null)
  const [done, setDone] = useState<DoneInfo | null>(null)
  const decidedHere = useRef(new Set<string>())
  // Plan: the full list and pane.
  const [selectedId, setSelectedId] = useState<string | null>(() => new URLSearchParams(window.location.search).get('card'))
  const [expanded, setExpanded] = useState<Set<string>>(new Set())
  const [mapSel, setMapSel] = useState<MapSelection>({})
  const [drawer, setDrawer] = useState<DrawerView>(null)
  const [fresh, setFresh] = useState<Set<string>>(new Set())
  const seenEvents = useRef<Set<string> | null>(null)
  const seenCards = useRef<Set<string> | null>(null)
  const lastStatus = useRef<Map<string, string> | null>(null)
  const offset = useRef(0)
  const phone = !useMedia('(min-width: 1024px)')
  const narrow = useMedia('(max-width: 767px)')
  // Opened from a push alert (/d/<id>?talk=1): the card rings as an incoming call.
  const [ringing, setRinging] = useState(new URLSearchParams(window.location.search).get('talk') === '1')
  const stopRinging = () => {
    setRinging(false)
    window.history.replaceState(null, '', window.location.pathname)
  }
  const go = useCallback((to: string) => {
    window.history.pushState(null, '', to)
    setPath(window.location.pathname)
    const card = new URLSearchParams(window.location.search).get('card')
    if (card) setSelectedId(card)
    window.scrollTo(0, 0)
  }, [])

  const live = useLive()
  const pending = pendingOf(live).length + drafts

  const load = useCallback(async () => {
    try {
      const s = await fetchState()
      offset.current = new Date(s.now).getTime() - Date.now()
      setNowMs(Date.now() + offset.current)
      setState(s)
      setError(false)

      // A new portal drop: say the agents are reading it (and pulse its place on the map).
      const ev = new Set(s.events.map((e) => e.id))
      if (seenEvents.current) {
        const added = s.events.filter((e) => !seenEvents.current!.has(e.id))
        if (added.length) {
          const e = added[0]
          const name = (e.path || e.file || '').split('/').pop()
          setToast(`New file: ${name}. Your agents are reading it.`)
          setPulseNode(e.node ?? null)
          window.setTimeout(() => setToast(null), 5000)
          window.setTimeout(() => setPulseNode(null), 4500)
        }
      }
      seenEvents.current = ev

      const ids = new Set(s.cards.filter((c) => c.status === 'open').map((c) => c.id))
      if (seenCards.current) {
        const added = [...ids].filter((id) => !seenCards.current!.has(id))
        if (added.length) {
          setFresh((f) => new Set([...f, ...added]))
          window.setTimeout(() => setFresh((f) => new Set([...f].filter((x) => !added.includes(x)))), 2500)
        }
      }
      seenCards.current = ids

      // Decided elsewhere (on a call): show "Done" for it too, unless a routine did it.
      const prev = lastStatus.current
      if (prev) {
        const c = s.cards.find((x) => prev.get(x.id) === 'open' && DECIDED.includes(x.status) && !decidedHere.current.has(x.id))
        const acts = c ? s.activity.filter((a) => a.card === c.id) : []
        if (c && !acts.some((a) => viaOf(a)?.kind === 'routine')) {
          const a = acts.find((x) => viaOf(x)?.kind === 'voice') ?? acts[0]
          decidedHere.current.add(c.id)
          void finish(s, {
            card: c,
            text: a ? stop(tidy(a.text)) : `${DONE_WORD[c.status] ?? 'Done'}.`,
            sub: viaOf(a ?? { text: '', kind: '' })?.kind === 'voice' ? 'Decided on the call.' : 'Decided elsewhere.',
            actionId: actionIdOf(a),
          })
        }
      }
      lastStatus.current = new Map(s.cards.map((c) => [c.id, c.status]))
    } catch {
      setError(true)
    }
  }, [])

  async function finish(s: State, d: { card: Card; text: string; sub: string; actionId: string | null }) {
    const more = lookAlikes(d.card, s).length
    const offer = more > 0 && !(await hasRoutine(d.card.id)) ? more : 0
    setDone({ ...d, offer, k: Date.now() })
  }

  useEffect(() => {
    void load()
    const poll = window.setInterval(load, POLL_MS)
    const tick = window.setInterval(() => setNowMs(Date.now() + offset.current), 15000)
    const nav = () => setPath(window.location.pathname)
    window.addEventListener('popstate', nav)
    return () => { clearInterval(poll); clearInterval(tick); window.removeEventListener('popstate', nav) }
  }, [load])

  // Voice drafts waiting in Routines count towards "Your routines want to do N things".
  useEffect(() => {
    const get = async () => {
      try {
        const r = await fetch('/api/routines/drafts')
        if (r.ok) setDrafts(((await r.json()).drafts ?? []).filter((x: { routine?: { id?: string } }) => x?.routine?.id).length)
      } catch { /* optional */ }
    }
    void get()
    const t = window.setInterval(get, 30000)
    return () => clearInterval(t)
  }, [])

  const sec = useMemo(() => (state ? sections(state) : null), [state])
  const order = useMemo(() => (sec ? visibleOrder(sec, expanded) : []), [sec, expanded])
  const today = useMemo(() => (state ? todayOrder(state) : []), [state])

  // Plan (desk): j / k / arrows walk the list, the pane follows.
  const onPlan = path.startsWith('/plan')
  useEffect(() => {
    if (narrow || !onPlan || !sec) return
    const onKey = (e: KeyboardEvent) => {
      const t = e.target
      if (t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return
      if (e.metaKey || e.ctrlKey || e.altKey || drawer) return
      const k = e.key
      const down = k === 'j' || k === 'J' || k === 'ArrowDown'
      const up = k === 'k' || k === 'K' || k === 'ArrowUp'
      if (!down && !up) return
      e.preventDefault()
      const cur = selectedId ?? order[0] ?? null
      const i = cur ? order.indexOf(cur) : -1
      const n = i < 0 ? 0 : Math.min(order.length - 1, Math.max(0, i + (down ? 1 : -1)))
      const id = order[n]
      if (!id) return
      setSelectedId(id)
      const g = sec.needs.find((x) => x.cards.length > 1 && x.lead.id !== id && x.cards.some((c) => c.id === id))
      if (g) setExpanded((ex) => new Set([...ex, g.key]))
      document.getElementById(`row-${id}`)?.scrollIntoView({ block: 'nearest' })
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [narrow, onPlan, sec, order, selectedId, drawer])

  if (!state || !sec) {
    return <div className="grid h-full place-items-center text-[15px] text-ink-3">{error ? 'Cannot reach the server.' : 'Loading…'}</div>
  }

  const single = path.match(/^\/d\/(.+)$/)
  const page: Page | null = single || path === '/' ? 'today' : path.startsWith('/plan') ? 'plan' : path.startsWith('/suppliers') ? 'suppliers' : path.startsWith('/routines') ? 'routines' : 'today'
  // Routines is its own page; "Show me how" lands there drafting from the decision.
  const openRoutines = (request?: { cardId: string; k: number }) =>
    go(request ? `/routines?draft=${encodeURIComponent(request.cardId)}` : '/routines')
  const truck = trucksLeave(state, nowMs)
  const open = today.length
  const status = (
    <>
      {truck && <span className="font-medium text-ink">{truck}</span>}
      {truck && (open > 0 || !phone || done) && ' · '}
      {phone && open > 0 ? (
        page === 'today'
          ? <button className="cursor-pointer hover:text-ink" onClick={() => go('/plan')}>{open} {open === 1 ? 'decision' : 'decisions'}</button>
          : `${open} ${open === 1 ? 'decision' : 'decisions'}`
      ) : done && open === 0 ? 'nothing else due' : open > 0 ? `${open} ${open === 1 ? 'decision needs' : 'decisions need'} you` : phone ? null : 'nothing needs you'}
    </>
  )
  const bar = (
    <TopBar
      page={page}
      go={go}
      onRoutines={() => openRoutines()}
      status={status}
      bell={<AlertsButton />}
      phone={phone}
      routinesBadge={pending}
    />
  )
  const routines = <RoutinesLive state={state} />
  const overlays = (
    <>
      {toast && (
        <div className="toast-in t-small fixed left-1/2 top-[76px] z-50 -translate-x-1/2 rounded-full bg-ink px-4 py-2 text-white shadow-lg" role="status">
          {toast}
        </div>
      )}
      <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
      {routines}
    </>
  )

  // ------------------------------------------------------------ Today (/ and /d/<id>)
  if (page === 'today') {
    const pinned = single ? state.cards.find((c) => c.id === decodeURIComponent(single[1])) ?? null : null
    const pinnedOpen = pinned && pinned.status !== 'open' ? null : pinned
    const card = single
      ? pinnedOpen ?? (done ? null : today[0] ?? null)
      : today.find((c) => c.id === focusId) ?? today[0] ?? null
    return (
      <div className="flex min-h-full flex-col bg-ground">
        {bar}
        <Today
          state={state}
          nowMs={nowMs}
          phone={phone}
          card={card}
          order={today}
          onFocus={(id) => { setFocusId(id); if (single) go('/') }}
          done={done}
          onDone={(d) => { decidedHere.current.add(d.card.id); void finish(state, d) }}
          onClearDone={() => { setDone(null); if (single) go('/') }}
          onChanged={load}
          onRoutines={openRoutines}
          go={go}
          ringing={ringing && !!pinnedOpen && card?.id === pinnedOpen.id}
          onRingingDone={stopRinging}
          pending={pending}
        />
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ Routines
  if (page === 'routines') {
    return (
      <div className="flex min-h-full flex-col bg-ground">
        {bar}
        <Routines state={state} onChanged={load} phone={narrow} />
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ Suppliers
  if (page === 'suppliers') {
    const list = (
      <SupplierList state={state} nowMs={nowMs} selection={mapSel} onSelect={setMapSel} onOpen={(id) => go(`/plan?card=${encodeURIComponent(id)}`)} />
    )
    if (narrow) {
      return (
        <div className="flex min-h-full flex-col bg-ground">
          {bar}
          <div className="relative h-[300px] shrink-0">
            <SupplyMap state={state} hoverRoutes={[]} selection={mapSel} onSelect={setMapSel} pulseNode={pulseNode} />
          </div>
          <MapLegend className="px-6 pt-3" />
          <div className="px-6 pb-16 pt-8">{list}</div>
          {overlays}
        </div>
      )
    }
    return (
      <div className="flex h-full flex-col bg-ground">
        {bar}
        <div className="flex min-h-0 flex-1">
          <div className="flex min-w-0 flex-1 flex-col pb-6 pl-6">
            <div className="relative min-h-[420px] flex-1">
              <SupplyMap state={state} hoverRoutes={[]} selection={mapSel} onSelect={setMapSel} pulseNode={pulseNode} />
            </div>
            <MapLegend className="pt-3" />
          </div>
          <aside className="scroll-thin w-[380px] shrink-0 overflow-y-auto px-10 pb-16 pt-6 xl:w-[420px]" aria-label="Suppliers">{list}</aside>
        </div>
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ Plan: timeline and every decision
  const groupOf = (c: Card) => sec.needs.find((g) => g.cards.some((x) => x.id === c.id)) ?? null
  const selected = selectedId ? state.cards.find((c) => c.id === selectedId) ?? null : null
  const offerFor = (c: Card): Offer | null => {
    if (done?.card.id !== c.id || !done.offer) return null
    const k = groupKey(c)
    return {
      more: state.cards.filter((x) => x.id !== c.id && x.status === 'open' && groupKey(x) === k).length,
      onYes: () => { openRoutines({ cardId: c.id, k: Date.now() }); setDone(null) },
      onNext: () => setDone(null),
    }
  }
  const select = (id: string | null) => {
    setSelectedId(id)
    if (!id) return
    const g = sec.needs.find((x) => x.cards.length > 1 && x.lead.id !== id && x.cards.some((c) => c.id === id))
    if (g) setExpanded((e) => new Set([...e, g.key]))
  }
  const toggle = (key: string) =>
    setExpanded((e) => { const n = new Set(e); if (n.has(key)) n.delete(key); else n.add(key); return n })
  const openOnPhone = (id: string) => go(`/d/${encodeURIComponent(id)}`)
  const timeline = (
    <LaunchTimeline state={state} nowMs={nowMs} selectedId={selectedId} onSelect={(id) => (narrow ? openOnPhone(id) : select(id))} compact={narrow} />
  )
  const list = (
    <DecisionList
      state={state}
      nowMs={nowMs}
      sec={sec}
      selectedId={narrow ? null : selectedId ?? order[0] ?? null}
      onSelect={narrow ? openOnPhone : select}
      expanded={expanded}
      onToggle={toggle}
      fresh={fresh}
    />
  )

  if (narrow) {
    return (
      <div className="flex min-h-full flex-col bg-ground">
        {bar}
        <div className="border-b border-hair px-6 pb-2 pt-2">{timeline}</div>
        <div className="px-3">{list}</div>
        {overlays}
      </div>
    )
  }
  const first = order[0] ?? null
  const shown = selected ?? (first ? state.cards.find((c) => c.id === first) ?? null : null)
  return (
    <div className="flex h-full flex-col bg-ground">
      {bar}
      <div className="shrink-0 border-b border-hair px-8 pb-4 xl:px-12">{timeline}</div>
      <div className="flex min-h-0 flex-1">
        <aside className="scroll-thin w-[340px] shrink-0 overflow-y-auto pl-5 pr-3 xl:w-[380px] xl:pl-9" aria-label="All decisions">{list}</aside>
        <main className="scroll-thin min-w-0 flex-1 overflow-y-auto">
          <div className="max-w-[720px] px-10 pb-24 pt-10 xl:ml-[4vw] xl:px-12">
            {shown ? (
              <DecisionPane
                key={shown.id}
                card={shown}
                state={state}
                nowMs={nowMs}
                group={groupOf(shown)}
                onChanged={load}
                onDrawer={(card, tab) => setDrawer({ card, tab })}
                offer={offerFor(shown)}
                keys
              />
            ) : (
              <p className="t-body pt-24 text-ink-2">Nothing here yet.</p>
            )}
          </div>
        </main>
      </div>
      {overlays}
    </div>
  )
}

const stop = (t: string) => (/[.!?]$/.test(t) ? t : `${t}.`)

// A routine already written from this card: do not offer to automate it again.
async function hasRoutine(cardId: string): Promise<boolean> {
  try {
    const r = await fetch('/api/routines')
    if (!r.ok) return false
    const { routines } = (await r.json()) as { routines: { created_from?: string }[] }
    return routines.some((x) => x.created_from === cardId)
  } catch {
    return false
  }
}
// What the Today screen says, derived from /api/state: which decision comes first, a short
// headline, the contradiction as one sentence, what it means for today's packing, and the
// recommendation. Nothing here knows a specific supplier, part or number.

import { DECIDED, costText, fmtDay, fmtTime, sentence, tidy, viaOf, type Card, type Evidence, type State } from '@/lib/api'
import { byUrgency, groupKey, launchAt, mismatchPair, sourceName, span } from '@/lib/decisions'

const ms = (iso?: string | null) => (iso ? new Date(iso).getTime() : NaN)

/** Open decisions for the viewer, most urgent first: the server's inbox order, then urgency. */
export function todayOrder(state: State): Card[] {
  const open = state.cards.filter((c) => c.status === 'open' && !c.routed_to_other)
  const rank = new Map(state.inbox_ids.map((id, i) => [id, i]))
  return open.sort((a, b) => {
    const ra = rank.get(a.id) ?? Infinity, rb = rank.get(b.id) ?? Infinity
    return ra !== rb ? ra - rb : byUrgency(a, b)
  })
}

/** "Trucks leave in 13 h 30 min"; null without a launch time. */
export function trucksLeave(state: State, nowMs: number): string | null {
  const at = launchAt(state)
  if (!at) return null
  const left = ms(at) - nowMs
  return left > 0 ? `Trucks leave in ${span(left)}` : 'The trucks have left'
}

export const plural = (n: number, one: string, many = `${one}s`) => `${n.toLocaleString('en-GB')} ${n === 1 ? one : many}`

// ---------------------------------------------------------------- words

/** "Game Card 128 GB" -> "game cards"; quoted names keep their case. */
export function noun(partName: string | null | undefined, many = true): string {
  if (!partName) return many ? 'parts' : 'part'
  if (partName.includes('"')) {
    const [head, ...rest] = partName.split(' ')
    return [head.toLowerCase() + (many && !head.endsWith('s') ? 's' : ''), ...rest].join(' ')
  }
  const words = partName.split(/\s+/)
  while (words.length > 1 && /^(\d+[\w.]*|[A-Z]{2,}|[–-])$/.test(words[words.length - 1])) words.pop()
  const out = words.map((w) => (/^[A-Z][a-z]+$/.test(w) ? w.toLowerCase() : w))
  const last = out.length - 1
  if (many && !/s$/i.test(out[last])) out[last] += 's'
  return out.join(' ')
}

const PARENS = /\s*\([^)]*\)/g
/** Text without the part's long product name: "Art Book Grand Heist 6 (96 p, hardcover)" -> "art books". */
export function plain(text: string | null | undefined, partName?: string | null): string {
  let t = tidy(text).replace(PARENS, '')
  if (partName) {
    const base = partName.replace(PARENS, '').trim()
    const i = t.indexOf(base)
    if (i >= 0) {
      const after = t.slice(i + base.length)
      // A run of capitalised words and numbers right after the name is the product title.
      const tail = after.match(/^(?:\s*[–-]\s*|\s+)(?:[A-Z][A-Za-z]*|\d+)(?:\s+(?:[A-Z][A-Za-z]*|\d+))*(?=[\s,.:;]|$)/)
      const before = t.slice(0, i)
      const counted = /\d\s*$/.test(before) && !/(^|\D)1\s*$/.test(before)
      const n = noun(partName, counted)
      t = before + (i === 0 ? n[0].toUpperCase() + n.slice(1) : n) + after.slice(tail ? tail[0].length : 0)
    }
  }
  return t.replace(/\s+([,.:;])/g, '$1').replace(/\s{2,}/g, ' ').trim()
}

const firstSentence = (t: string) => {
  const m = t.match(/^.*?[.!?](?=\s+[A-Z0-9]|$)/)
  return (m ? m[0] : t).trim()
}
const stop = (t: string) => (/[.!?]$/.test(t) ? t : `${t}.`)
const cap = (t: string) => (t ? t[0].toUpperCase() + t.slice(1) : t)

/** True when the goods a card is about arrive after the trucks leave. */
export function afterLaunch(card: Card, state: State): boolean {
  const l = launchAt(state)
  return !!(card.arrives_at && l && ms(card.arrives_at) > ms(l))
}

/** The big headline: plain words, one sentence, no part codes. */
export function headlineOf(card: Card, state: State): string {
  const h = plain(card.headline, card.part_name)
  if (afterLaunch(card, state)) {
    const n = tidy(card.headline).match(/\d[\d,.]*\d|\d/)?.[0]
    if (n) return `${n} ${noun(card.part_name, n !== '1')} will arrive after launch.`
  }
  // Drop a trailing ", but ..." clause on long headlines; the sentence below says it.
  const one = firstSentence(h).replace(/\s+on PO \d{6,}/g, '')
  const short = one.length > 70 ? one.replace(/,\s+(but|which|while)\b.*$/, '') : one
  return stop(cap(short))
}

/** One line for a list: shorter still. */
export function shortTitle(card: Card, state: State): string {
  return headlineOf(card, state)
    .replace(/\bwill arrive after launch\b/, 'arrive late')
    .replace(/^We have /, '')
    .replace(/\.$/, '')
}

/** "PackRight" from "Guangzhou PackRight", "Hwaseong" from "Hwaseong Memory". */
export function shortName(name?: string | null): string {
  if (!name) return ''
  const words = name.split(/\s+/)
  return words.find((w) => /^[A-Z][a-z]+[A-Z]/.test(w)) ?? words[0]
}

// ---------------------------------------------------------------- the contradiction

export interface Side {
  index: number
  ev: Evidence
  /** The words that become the tappable citation. */
  value: string
}
export interface Claim {
  sys: Side
  doc: Side
  /** Text around the two citations: before sys, between, after doc. */
  pre: string
  mid: string
  post: string
}

const ID = /\b[A-Z]{0,4}[ -]?\d{6,}\b/
function pick(v: string | number | undefined): string {
  const s = tidy(String(v ?? '')).replace(PARENS, '').replace(/\s+(?:on|for)\s+[A-Z]{1,4}\s*\d{6,}/g, '').trim()
  const segs = s.split(/\s+·\s+|,\s+(?=[a-z])/).map((x) => x.trim()).filter(Boolean)
  const useful = segs.filter((x) => !ID.test(x))
  const dated = useful.find((x) => /\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b|\b\d{1,2} [A-Z][a-z]{2}\b/.test(x) && /\d/.test(x))
  return (dated ?? useful[0] ?? s).replace(/\bdue\b/, 'by')
}

/** "shipping advice" from "Paper says · shipping advice Shipping_advice_020-... (KO/EN)". */
export function docKind(source?: string): string {
  return sourceName(source)
    .split(/\s+/)
    .filter((w) => w && !/[\d_]/.test(w) && !/^[A-Z]{2,}(-|$)/.test(w))
    .join(' ')
    .toLowerCase()
}

export function claimOf(card: Card): Claim | null {
  const pair = mismatchPair(card)
  if (!pair) return null
  const s = card.evidence[pair.sys], d = card.evidence[pair.doc]
  const sysWho = /\bSAP\b/.test(s.source ?? '') ? 'SAP' : 'The system'
  const sv = pick(s.value), dv = pick(d.value)
  const expects = /^\S+\s+by\b/.test(sv)
  const kind = docKind(d.source) || 'document'
  const owner = d.doc?.startsWith('suppliers/') && card.supplier_name ? `${shortName(card.supplier_name)}'s` : 'the'
  return {
    sys: { index: pair.sys, ev: s, value: sv },
    doc: { index: pair.doc, ev: d, value: dv },
    pre: `${sysWho} ${expects ? 'expects' : 'says'} `,
    mid: `, but ${owner} ${kind} says `,
    post: '.',
  }
}

/** The supporting sentence when there is no system-vs-document pair. */
export function summaryLine(card: Card): string {
  return card.summary ? stop(firstSentence(plain(card.summary, card.part_name))) : ''
}

// ---------------------------------------------------------------- for today

const WORDS = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve']
function hoursWords(h: number): string {
  if (h < 1) return `${Math.max(1, Math.round(h * 60))} minutes`
  const r = Math.round(h)
  return r <= 12 ? `${WORDS[r]} hour${r === 1 ? '' : 's'}` : `${r} hours`
}
const at = (iso: string, nowMs: number) =>
  fmtDay(iso) === fmtDay(new Date(nowMs).toISOString()) ? fmtTime(iso) : `${fmtDay(iso)} ${fmtTime(iso)}`

/** "Standard runs out of game cards at 17:00" + ", three hours before the trucks." */
export function forToday(card: Card, state: State, nowMs: number): { bold: string; rest: string } | null {
  const ed = state.clock?.editions.find((e) => e.edition === card.edition)
  const launch = launchAt(state)
  if (!ed) return null
  // The edition's stop belongs to this card only if this card is what breaks first. Otherwise
  // talk about this card's own part (when it runs dry), or say nothing: never borrow another
  // part's stop time for this decision.
  const ownStop = ed.breaks_first_card === card.id || !ed.breaks_first_card
  const stopsAt = ownStop ? ed.stops_at : card.runs_dry
  if (!stopsAt || (launch && ms(stopsAt) >= ms(launch))) return null
  const what = noun(card.part_name)
  const stopMs = ms(stopsAt)
  if (stopMs <= nowMs) return { bold: `${ed.label} is out of ${what} since ${at(stopsAt, nowMs)}`, rest: '.' }
  const gap = launch ? (ms(launch) - stopMs) / 3600000 : 0
  return {
    bold: `${ed.label} runs out of ${what} at ${at(stopsAt, nowMs)}`,
    rest: gap > 0.1 ? `, ${hoursWords(gap)} before the trucks.` : '.',
  }
}

// ---------------------------------------------------------------- recommendation and outcome

export const recommendedIndex = (card: Card) => Math.max(0, card.options.findIndex((o) => o.recommended))

export function actionText(card: Card, i: number): string {
  const o = card.options[i]
  return o ? stop(cap(plain(o.action, card.part_name))) : ''
}
export function costLine(card: Card, i: number): string {
  const c = costText(card.options[i]?.cost)
  return c === 'No cost' ? 'No cost.' : stop(c)
}
export const costsMoney = (card: Card, i: number) => costText(card.options[i]?.cost) !== 'No cost'

const PAST: Record<string, string> = {
  ask: 'Asked', tell: 'Told', order: 'Ordered', send: 'Sent', book: 'Booked', collect: 'Collected',
  call: 'Called', move: 'Moved', release: 'Released', hold: 'Held', request: 'Requested', confirm: 'Confirmed',
  correct: 'Corrected', switch: 'Switched', pay: 'Paid', accept: 'Accepted', approve: 'Approved',
  cancel: 'Cancelled', expedite: 'Expedited', fly: 'Flew', reserve: 'Reserved', notify: 'Notified',
}
/** "Asked Boise Semi for 6,800 game cards before launch." from the option's imperative. */
export function doneText(card: Card, i: number, status?: string): string {
  const a = actionText(card, i)
  if (status === 'escalated') return `Passed on to ${card.approver || 'the approver'}.`
  if (status === 'dismissed') return 'Taken off the list.'
  const m = a.match(/^(\w+)\s+(.*)$/)
  const past = m && PAST[m[1].toLowerCase()]
  return past ? `${past} ${m![2]}` : a ? `Approved: ${a[0].toLowerCase()}${a.slice(1)}` : 'Approved.'
}

/** Open look-alikes of a card (same supplier, kind and headline shape). */
export const lookAlikes = (card: Card, state: State) =>
  state.cards.filter((x) => x.id !== card.id && x.status === 'open' && !x.routed_to_other && groupKey(x) === groupKey(card))

/** Routine work since 18:00 yesterday (or the last 14 h). */
export function routineCount(state: State, nowMs: number): number {
  const since = nowMs - 14 * 3600000
  return state.activity.filter((a) => viaOf(a)?.kind === 'routine' && (!a.at || ms(a.at) >= since)).length
}

export const isDecided = (status: string) => DECIDED.includes(status)

/** The launch status line for the all-clear screen: honest when an edition stops. */
export function launchStatus(state: State, nowMs: number): string {
  const launch = launchAt(state)
  const stops = (state.clock?.editions ?? []).filter((e) => e.stops_at && (!launch || ms(e.stops_at) < ms(launch)))
  if (stops.length) {
    const e = stops.sort((a, b) => ms(a.stops_at) - ms(b.stops_at))[0]
    const past = ms(e.stops_at) <= nowMs
    return `${e.label} ${past ? 'is waiting for parts' : `stops at ${at(e.stops_at!, nowMs)} unless parts arrive`}. Your agents are on it.`
  }
  return launch ? `On track for the trucks at ${fmtTime(launch)}.` : 'On track.'
}

export const sentenceOf = sentence
import { useSyncExternalStore } from 'react'
import { call, type Mode, type Proposal, type Routine, type Run, type WouldHandle } from './types'

// What the routines prepared for the buyer, shared by the Routines sheet, the decision pane and
// the inbox list: proposals waiting for an OK, routines that would handle a card, and actions
// undone on this screen. Refreshed on the app's own refresh (see `refreshLive`), never on its
// own timer. Endpoints that are not there yet (404) simply count as empty.

/** A routine the voice assistant drafted during a call (GET /api/routines/drafts). */
export interface VoiceDraft { card_id: string; instruction?: string; at?: string; via?: string; routine: Routine; preview?: Run }

interface Live {
  proposals: Proposal[]
  /** Voice drafts not hidden on this device and not saved as a routine yet. */
  drafts: VoiceDraft[]
  would: Record<string, WouldHandle[]>
  /** Action id -> "undone" or the reason it could not be undone. */
  undo: Record<string, { ok: boolean; reason?: string }>
  /** Proposals the buyer just accepted or skipped, hidden before the server agrees. */
  settled: Set<string>
}

const HIDDEN_KEY = 'ask-soony.hidden-routine-drafts'
function readHidden(): Set<string> {
  try { return new Set(JSON.parse(localStorage.getItem(HIDDEN_KEY) ?? '[]') as string[]) } catch { return new Set() }
}
let hidden = readHidden()
let allDrafts: VoiceDraft[] = []
const visibleDrafts = () => allDrafts.filter((d) => !hidden.has(d.routine.id))

let live: Live = { proposals: [], drafts: [], would: {}, undo: {}, settled: new Set() }
const subs = new Set<() => void>()
const set = (next: Partial<Live>) => { live = { ...live, ...next }; subs.forEach((f) => f()) }
const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f) } }

