const cap = (t: string) => (t ? t[0].toUpperCase() + t.slice(1) : t)

function doneFrom(card: Card, i: number, status?: string): string {
  const a = actionText(card, i)
  const m = a.match(/^(\w+)\s+(.*)$/)
  const PAST: Record<string, string> = {
    ask: 'Asked', tell: 'Told', order: 'Ordered', send: 'Sent', book: 'Booked', collect: 'Collected', call: 'Called',
    move: 'Moved', release: 'Released', request: 'Requested', confirm: 'Confirmed', correct: 'Corrected', pay: 'Paid',
    accept: 'Accepted', cancel: 'Cancelled', expedite: 'Expedited', reserve: 'Reserved', notify: 'Notified', fly: 'Flew',
  }
  const past = m && PAST[m[1].toLowerCase()]
  // Short names and no order numbers: "Asked PackRight to make the order to rev C."
  const calm = (t: string) =>
    (card.supplier_name ? t.split(card.supplier_name).join(shortName(card.supplier_name)) : t).replace(/\bPO \d{6,}/g, 'the order')
  if (past) return calm(`${past} ${m![2]}`)
  return calm(status === 'sent' ? `Sent: ${a}` : `Approved: ${a}`)
}

const DbIcon = () => <Database aria-hidden="true" />
const DocIcon = () => <FileText aria-hidden="true" />

function ClaimLine({ claim, late, open, onOpen }: { claim: Claim; late: boolean; open: number | null; onOpen: (i: number) => void }) {
  return (
    <>
      {claim.pre}
      <button className="cite" aria-expanded={open === claim.sys.index} aria-haspopup="dialog" onClick={() => onOpen(claim.sys.index)}>
        {claim.sys.value}<DbIcon />
      </button>
      {claim.mid}
      <button className={cn('cite', late && 'late')} aria-expanded={open === claim.doc.index} aria-haspopup="dialog" onClick={() => onOpen(claim.doc.index)}>
        {claim.doc.value}<DocIcon />
      </button>
      {claim.post}
    </>
  )
}

/** A sentence whose numbers, when found in a source, open that source. */
function Cited({ text, anchors, onOpen, open }: { text: string; anchors: Record<number, Anchor[]> | null; onOpen: (i: number) => void; open: number | null }) {
  if (!text) return null
  const flat = Object.entries(anchors ?? {}).flatMap(([i, as]) => as.map((a) => ({ i: Number(i), a })))
  const parts: ReactNode[] = []
  let last = 0
  for (const m of text.matchAll(NUM_OR_ID)) {
    const hit = flat.find((x) => x.a.matched.includes(normTok(m[0])))
    if (!hit || !/\d/.test(m[0])) continue
    parts.push(text.slice(last, m.index))
    parts.push(
      <button key={m.index} className="cite" aria-expanded={open === hit.i} aria-haspopup="dialog" onClick={() => onOpen(hit.i)}>
        {m[0]}
      </button>,
    )
    last = (m.index ?? 0) + m[0].length
  }
  parts.push(text.slice(last))
  return <>{parts}</>
}

// ---------------------------------------------------------------- the source sheet

const SYS = /system|sap|erp/i
function sideLabel(card: Card, ev: Evidence): { who: string; isSys: boolean } {
  const isSys = SYS.test(ev.source ?? '')
  if (isSys) return { who: /\bSAP\b/.test(ev.source ?? '') ? 'SAP says' : 'The system says', isSys }
  const kind = docKind(ev.source) || 'the document'
  const owner = ev.doc?.startsWith('suppliers/') && card.supplier_name ? `${shortName(card.supplier_name)}'s ` : 'The '
  return { who: `${owner}${kind} says`.replace(/^The the/, 'The'), isSys }
}
const where = (a?: Anchor, ev?: Evidence) =>
  a ? (a.kind === 'table' || a.kind === 'text' ? `row ${(a.row ?? 0) + 1}` : `page ${a.page ?? 1}`) : ev?.page ? `page ${ev.page}` : ''

function SourceSheet({
  card, claim, index, anchors, ready, onIndex,
}: { card: Card; claim: Claim | null; index: number | null; anchors: Record<number, Anchor[]> | null; ready: boolean; onIndex: (i: number | null) => void }) {
  const ev = index != null ? card.evidence[index] : null
  const a = index != null ? anchors?.[index]?.[0] : undefined
  const otherIndex = claim && index != null ? (index === claim.sys.index ? claim.doc.index : index === claim.doc.index ? claim.sys.index : null) : null
  const other = otherIndex != null ? card.evidence[otherIndex] : null
  const otherA = otherIndex != null ? anchors?.[otherIndex]?.[0] : undefined
  const label = ev ? sideLabel(card, ev) : null
  const lang = ev ? languageOf(ev.source, ev.language) : null
  const head = ev
    ? [label!.isSys ? (/\bSAP\b/.test(ev.source ?? '') ? 'SAP' : 'System') : card.supplier_name, [docKind(ev.source), where(a, ev)].filter(Boolean).join(', '), lang]
        .filter(Boolean).join(' · ')
    : ''
  const english = ev?.translation ? ev.translation.split(' = ').pop() : null
  const original = a ? fileUrl(a) : ev?.doc ? `/api/file?path=${encodeURIComponent(ev.doc)}${ev.page ? `#page=${ev.page}` : ''}` : null

  return (
    <Dialog.Root open={index != null} onOpenChange={(o) => !o && onIndex(null)}>
      <Dialog.Portal>
        <Dialog.Overlay className="fade fixed inset-0 z-40 bg-[rgba(24,24,26,.28)]" />
        <Dialog.Content
          aria-describedby={undefined}
          className={cn(
            'sheet-up fixed z-50 overflow-y-auto bg-ground focus:outline-none',
            'inset-x-0 bottom-0 max-h-[88vh] rounded-t-[22px] px-6 pb-[max(36px,env(safe-area-inset-bottom))] pt-3 shadow-[0_-10px_40px_-16px_rgba(0,0,0,.25)]',
            'md:inset-x-auto md:bottom-auto md:left-1/2 md:top-[8vh] md:max-h-[84vh] md:w-[640px] md:-translate-x-1/2 md:rounded-2xl md:px-8 md:pb-8 md:pt-7 md:shadow-[0_20px_60px_-20px_rgba(0,0,0,.3)]',
          )}
        >
          <div className="mx-auto mb-5 h-[5px] w-9 rounded-full bg-hair md:hidden" aria-hidden="true" />
          {ev && (
            <>
              <Dialog.Title className="t-small font-normal text-ink-3">{head}</Dialog.Title>
              <div className="mt-3 overflow-hidden rounded-xl bg-soft p-3">
                {a ? (
                  <AnchorCrop key={`${index}-${a.doc}`} anchor={a} />
                ) : !ready ? (
                  <p className="t-small p-2 text-ink-3">Finding it in the documents…</p>
                ) : (
                  <p className="t-small whitespace-pre-wrap p-2 leading-[1.9] text-ink-2"><Marked text={tidy(ev.quote) || String(ev.value ?? '')} value={String(ev.value ?? '')} /></p>
                )}
              </div>
              {english ? (
                <p className="t-body mt-4 text-ink">{english}</p>
              ) : a && ev.quote ? (
                <p className="t-small mt-3 text-ink-3">{tidy(ev.quote)}</p>
              ) : null}

              {other && (
                <button
                  onClick={() => onIndex(otherIndex)}
                  className="t-body mt-7 grid w-full cursor-pointer grid-cols-[20px_1fr] gap-x-2.5 text-left text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
                >
                  <span className="mt-1 text-ink-3">{sideLabel(card, other).isSys ? <Database size={16} /> : <FileText size={16} />}</span>
                  <span>
                    <span className="font-medium text-ink">{sideLabel(card, other).who} {splitValue(other.value).big}</span>{' '}
                    {splitValue(other.value).rest}
                  </span>
                  <span className="t-small col-start-2 text-ink-3">{cap([docKind(other.source), where(otherA, other)].filter(Boolean).join(', '))}</span>
                </button>
              )}

              <div className="mt-7 flex items-center gap-4">
                {original && (
                  <a href={original} target="_blank" rel="noreferrer" className="t-small shrink-0 text-accent hover:underline">Open original</a>
                )}
                <Dialog.Close className="t-body h-[52px] flex-1 cursor-pointer rounded-[14px] bg-soft font-medium text-ink hover:bg-hair focus-visible:outline-2 focus-visible:outline-accent">
                  Back
                </Dialog.Close>
              </div>
            </>
          )}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/** The quote with the value's numbers highlighted (when no page or row was found). */
function Marked({ text, value }: { text: string; value: string }) {
  const nums = new Set((value.match(/\d[\d,.]*\d|\d/g) ?? []).map(normTok))
  const parts: ReactNode[] = []
  let last = 0
  for (const m of text.matchAll(/\d[\d,.]*\d|\d/g)) {
    if (!nums.has(normTok(m[0]))) continue
    parts.push(text.slice(last, m.index), <mark key={m.index} className="rounded-[3px] bg-mark px-1 font-semibold text-[#111]">{m[0]}</mark>)
    last = (m.index ?? 0) + m[0].length
  }
  parts.push(text.slice(last))
  return <>{parts}</>
}

// ---------------------------------------------------------------- done

function DoneView(p: Props & { done: DoneInfo }) {
  const { done, state, phone } = p
  const live = useLive()
  const outcome = done.actionId ? live.undo[done.actionId] : undefined
  const [undoing, setUndoing] = useState(false)
  const next = p.order.find((c) => c.id !== done.card.id) ?? null
  const offer = done.offer > 0 && !outcome?.ok
  const who = shortName(done.card.supplier_name)

  const undo = async () => {
    if (!done.actionId) return
    setUndoing(true)
    const r = await undoAction(done.actionId)
    setUndoing(false)
    if (r.ok) p.onChanged()
  }

  const primary = offer
    ? { label: 'Show me how', onClick: () => { p.onClearDone(); p.onRoutines({ cardId: done.card.id, k: Date.now() }) } }
    : next
      ? { label: 'Next decision', onClick: () => { p.onFocus(next.id); p.onClearDone() } }
      : null
  const quiet = offer ? { label: 'Not now', onClick: p.onClearDone } : null

  return (
    <section className="rise" aria-live="polite">
      <div className="mb-6 grid h-10 w-10 place-items-center rounded-full bg-soft text-ink"><Check size={20} strokeWidth={1.75} /></div>
      <h1 className="t-big text-ink">{outcome?.ok ? 'Undone.' : `Done. ${done.text}`}</h1>
      <p className="t-body mt-6 text-ink-2">
        {outcome?.ok ? 'It is back on your list.' : done.sub}{' '}
        {done.actionId && !outcome && (
          <button onClick={undo} disabled={undoing} className="uline">{undoing ? 'Undoing…' : 'Undo'}</button>
        )}
        {outcome && !outcome.ok && <span className="t-small block pt-2 text-ink-3">Undo: {outcome.reason}</span>}
      </p>

      <div className="h-14" />
      {offer ? (
        <div>
          <p className="t-body text-ink">
            {plural(done.offer, 'more like this', 'more like this')}{who ? ` from ${who}` : ''}. Handle them the same way?
          </p>
          <p className="t-small dot-routine mt-7 text-routine">You'll see a test run first. It starts by asking: it prepares them, you send with one tap.</p>
        </div>
      ) : next ? (
        <p className="t-body text-ink-2">Next: <span className="text-ink">{headlineOf(next, state)}</span></p>
      ) : (
        <p className="t-body text-ink-2">Nothing else needs you. <button className="uline" onClick={p.onClearDone}>See the day</button></p>
      )}

      {(primary || quiet) && (
        <div className={cn(phone ? 'fixed inset-x-0 bottom-0 z-20 bg-gradient-to-t from-ground from-70% to-ground/0 px-6 pb-[max(28px,env(safe-area-inset-bottom))] pt-8' : 'mt-10')}>
          <div className={cn(phone ? 'mx-auto grid max-w-[520px] justify-items-center gap-3.5' : 'flex items-center gap-6')}>
            {primary && (
              <button
                onClick={primary.onClick}
                autoFocus={!phone}
                className={cn(
                  't-body inline-flex cursor-pointer items-center justify-center rounded-xl bg-accent font-medium text-white shadow-[0_1px_2px_rgba(35,72,208,.25)] hover:bg-[#1d3db5] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent',
                  phone ? 'h-[54px] w-full rounded-[14px]' : 'h-12 px-7',
                )}
              >
                {primary.label}
              </button>
            )}
            {quiet && (
              <button onClick={quiet.onClick} className={cn('cursor-pointer text-ink-2 hover:text-ink', phone ? 't-small' : 't-body')}>{quiet.label}</button>
            )}
          </div>
        </div>
      )}
    </section>
  )
}

// ---------------------------------------------------------------- all clear

function AllClear({
  state, nowMs, handled, onRoutines, onReview, onChanged, go,
}: { state: State; nowMs: number; handled: number; onRoutines: (r?: { cardId: string; k: number }) => void; onReview: Review; onChanged: () => void; go: (p: string) => void }) {
  const waiting = state.cards.filter((c) => (c.status === 'open' && c.routed_to_other) || c.status === 'escalated').length
  const live = useLive()
  const pending = pendingOf(live)
  return (
    <section className="rise pt-[16vh] lg:pt-[10vh]">
      <h1 className="t-big text-ink">Nothing needs you.</h1>
      <p className="t-body mt-6 text-ink-2">{launchStatus(state, nowMs)}</p>
      <div className="t-small mt-10 grid gap-3.5 text-ink-2">
        <span>Watching {plural(state.shipments.length, 'shipment')}<button className="uline ml-1.5" onClick={() => go('/suppliers')}>see</button></span>
        {waiting > 0 && <span>{plural(waiting, 'decision')} with others<button className="uline ml-1.5" onClick={() => go('/plan')}>see</button></span>}
        {handled > 0 && (
          <RoutineLine links={[{ label: 'see', onClick: () => onRoutines() }, { label: 'undo', onClick: () => go('/plan#handled') }]}>
            {handled} handled by your routines {new Date(nowMs).getHours() < 11 ? 'overnight' : 'today'}
          </RoutineLine>
        )}
        {/* One routine waiting: its own line below names it. Several: one count. */}
        {pending.length > 0 && new Set(pending.map((x) => x.routine_id)).size > 1 && (
          <RoutineLine links={[{ label: 'review', onClick: () => onReview(pending) }]}>{pending.length} waiting for your OK</RoutineLine>
        )}
        <Automation state={state} onRoutines={onRoutines} onReview={onReview} onChanged={onChanged} className="grid gap-3.5" />
      </div>
      {state.last_check_at && <p className="t-small mt-16 text-ink-3">Last checked the portal at {when(state.last_check_at, nowMs)}.</p>}
    </section>
  )
}

/**
 * Automation where the decision happens, one quiet line each: what a routine would do with the
 * focused decision, what routines prepared and wait to send, and routines drafted on a call.
 */
function Automation({
  state, card, onRoutines, onReview, onChanged, className,
}: { state: State; card?: Card; onRoutines: (r?: { cardId: string; k: number }) => void; onReview: Review; onChanged: () => void; className?: string }) {
  const live = useLive()
  const pending = pendingOf(live)
  const mine = card ? pending.filter((x) => x.card_id === card.id) : []
  const others = card ? pending.filter((x) => x.card_id !== card.id) : []
  const asking = new Set(mine.map((x) => x.routine_id))
  const would = card && card.status === 'open' ? (live.would[card.id] ?? []).filter((w) => !asking.has(w.routine_id)) : []
  const drafts = live.drafts
  // On All clear several routines fold into the count line above; a single one is named here.
  const all = groupProposals(card ? others : pending, state)
  const groups = !card && all.length > 1 ? [] : all
  if (!mine.length && !would.length && !groups.length && !drafts.length) return null
  return (
    <div className={cn('grid gap-3', className)}>
      {mine.length > 0 && (
        <RoutineLine links={[{ label: 'review', onClick: () => onReview(mine) }]}>
          Your routine ‘{mine[0].routine_name}’ prepared {mine.length === 1 ? 'this for you' : `${mine.length} steps for this`}
        </RoutineLine>
      )}
      {would.slice(0, 1).map((w) => <WouldLine key={w.routine_id} w={w} onChanged={onChanged} />)}
      <ProposalLines groups={groups} onReview={onReview} max={card ? 1 : 2} />
      {drafts.length > 0 && (
        <RoutineLine links={[{ label: 'review', onClick: () => onRoutines() }]}>
          {drafts.length === 1 ? <>Drafted from your call: ‘{drafts[0].routine.name}’</> : <>{drafts.length} routines drafted from your calls</>}
        </RoutineLine>
      )}
    </div>
  )
}

function FootLines({ handled, onRoutines, nowMs, center }: { handled: number; onRoutines: () => void; nowMs: number; center: boolean }) {
  if (!handled) return null
  return (
    <div className={cn('flex', center && 'justify-center')}>
      <RoutineLine links={[{ label: 'see', onClick: onRoutines }]}>
        {handled} handled by your routines {new Date(nowMs).getHours() < 11 ? 'overnight' : 'today'}
      </RoutineLine>
    </div>
  )
}

import { useState, type ReactNode } from 'react'
import { DONE_WORD, ago, fmtNum, tidy, type Card, type State } from '@/lib/api'
import { sameIssueOn, when, type Group, type Sections } from '@/lib/decisions'
import { shortName, shortTitle } from '@/lib/today'
import { cn } from '@/lib/utils'
import { UndoAction } from './routines/Undo'

interface Props {
  state: State
  nowMs: number
  sec: Sections
  selectedId: string | null
  onSelect: (id: string) => void
  expanded: Set<string>
  onToggle: (key: string) => void
  fresh: Set<string>
}

/** The quiet section label, as on Today. */
export const HEADING = 't-small text-ink-3'

/** Ids in the order j/k walks them: one per row, a group's members only when it is open. */
export function visibleOrder(sec: Sections, expanded: Set<string>): string[] {
  return [
    ...sec.needs.flatMap((g) => (expanded.has(g.key) ? g.cards.map((c) => c.id) : [g.lead.id])),
    ...sec.waiting.map((c) => c.id),
    ...sec.handled.flatMap((h) => (h.card ? [h.card.id] : [])),
    ...sec.done.map((c) => c.id),
  ]
}

const first = (s?: string) => (!s ? '' : /\s[a-z]/.test(s) ? s : (s.split(' ').find((w) => !w.endsWith('.')) ?? s))

// Every decision as one quiet row: a dot, the short headline, the time. Red only on what misses
// the trucks, green only for work a routine did, the blue dot for the row in the pane.
export function DecisionList(p: Props) {
  const { state, sec } = p
  const [showDone, setShowDone] = useState(false)
  const suppliers = new Set(state.shipments.map((s) => s.supplier_id)).size
  const needN = sec.needs.reduce((n, g) => n + g.cards.length, 0)

  return (
    <div className="space-y-9 py-6">
      <Section title="Needs you" n={needN}>
        {sec.needs.length ? (
          sec.needs.map((g) => <GroupRow key={g.key} g={g} {...p} />)
        ) : (
          <li className="t-small px-3.5 text-ink-2">
            Nothing needs you. Agents are watching {state.shipments.length} shipments; last check {ago(state.last_check_at, p.nowMs)}.
          </li>
        )}
      </Section>

      {sec.waiting.length > 0 && (
        <Section title="Waiting on others" n={sec.waiting.length}>
          {sec.waiting.map((c) => (
            <Row key={c.id} card={c} {...p} sub={`${c.status === 'escalated' ? 'Waiting for' : 'With'} ${first(c.approver) || 'the approver'}`} quiet />
          ))}
        </Section>
      )}

      {sec.handled.length > 0 && (
        <section id="handled">
          <h2 className={cn(HEADING, 'dot-routine px-3.5 text-routine')}>Handled for you · {sec.handled.length}</h2>
          <ul className="mt-2">
            {sec.handled.map((h) => {
              const on = !!h.card && p.selectedId === h.card.id
              const body = (
                <>
                  <span className={cn('block truncate', on ? 'font-medium text-ink' : 'text-ink-2')}>{tidy(h.text)}</span>
                  <span className="mt-0.5 flex min-w-0 flex-wrap items-center gap-x-2 text-ink-3">
                    <span className="truncate text-routine">{h.routine}</span>
                    {h.at && <span>· {when(h.at, p.nowMs)}</span>}
                    {h.actionId && <UndoAction actionId={h.actionId} />}
                  </span>
                </>
              )
              // A div, not a button: the row holds its own Undo button.
              return (
                <li key={h.key}>
                  {h.card ? (
                    <div
                      role="button"
                      tabIndex={0}
                      id={`row-${h.card.id}`}
                      onClick={() => p.onSelect(h.card!.id)}
                      onKeyDown={(e) => { if (e.key === 'Enter' && e.target === e.currentTarget) p.onSelect(h.card!.id) }}
                      aria-current={on ? 'true' : undefined}
                      className={cn(rowCls, 'pl-[38px]', on && 'bg-soft')}
                    >
                      {body}
                    </div>
                  ) : (
                    <div className={cn(rowCls, 'cursor-default pl-[38px]')}>{body}</div>
                  )}
                </li>
              )
            })}
          </ul>
        </section>
      )}

      {sec.done.length > 0 && (
        <section>
          <button
            onClick={() => setShowDone(!showDone)}
            aria-expanded={showDone}
            className={cn(HEADING, 'cursor-pointer px-3.5 hover:text-ink focus-visible:outline-2 focus-visible:outline-accent')}
          >
            Decided by you · {sec.done.length} <span className="ml-1 border-b border-hair">{showDone ? 'hide' : 'show'}</span>
          </button>
          {showDone && (
            <ul className="mt-2">
              {sec.done.map((c) => (
                <Row
                  key={c.id}
                  card={c}
                  {...p}
                  quiet
                  sub={`${DONE_WORD[c.status] ?? 'Done'}${c.ui?.at ? ` ${when(c.ui.at, p.nowMs)}` : ''}`}
                />
              ))}
            </ul>
          )}
        </section>
      )}

      <p className="t-small px-3.5 text-ink-3">
        Watching {state.shipments.length} shipments from {suppliers} suppliers and every new portal file
        {state.read_since_6 > 0 ? ` (${state.read_since_6} read since 06:00)` : ''}. Last check {ago(state.last_check_at, p.nowMs)}.
      </p>
      <p className="t-small hidden px-3.5 text-ink-3 md:block"><kbd>J</kbd> <kbd>K</kbd> to move, <kbd>A</kbd> to approve</p>
    </div>
  )
}

function Section({ title, n, children }: { title: string; n: number; children: ReactNode }) {
  return (
    <section>
      <h2 className={cn(HEADING, 'px-3.5')}>{title} · {n}</h2>
      <ul className="mt-2">{children}</ul>
    </section>
  )
}

const rowCls =
  't-small relative block w-full cursor-pointer rounded-[10px] px-3.5 py-2.5 text-left hover:bg-soft/70 focus-visible:outline-2 focus-visible:outline-accent'

function Row({
  card, state, nowMs, selectedId, onSelect, fresh, sub, quiet, extra, selected,
}: Props & { card: Card; sub?: ReactNode; quiet?: boolean; extra?: ReactNode; selected?: boolean }) {
  const on = selected ?? selectedId === card.id
  const late = card.level === 'red' && card.status === 'open'
  const time = card.deadline && card.status === 'open' ? when(card.deadline, nowMs) : ''
  return (
    <li>
      <div
        role="button"
        tabIndex={0}
        id={`row-${card.id}`}
        onClick={() => onSelect(card.id)}
        onKeyDown={(e) => { if (e.key === 'Enter' && e.target === e.currentTarget) onSelect(card.id) }}
        aria-current={on ? 'true' : undefined}
        className={cn(rowCls, 'grid grid-cols-[8px_1fr_auto] items-baseline gap-x-3.5', on && 'bg-soft', fresh.has(card.id) && 'slide-in')}
      >
        <i
          className={cn('h-[7px] w-[7px] -translate-y-px rounded-full', on ? 'bg-accent' : late ? 'bg-late' : 'bg-ink-3', quiet && !on && 'bg-hair ring-1 ring-ink-3/40')}
          aria-hidden="true"
        />
        <span className="min-w-0">
          <span className={cn('line-clamp-2', on ? 'font-medium text-ink' : quiet ? 'text-ink-2' : 'text-ink')}>
            {shortTitle(card, state)}
          </span>
          <span className="mt-0.5 flex min-w-0 items-center gap-2 text-ink-3">
            <span className="truncate">{sub ?? (shortName(card.supplier_name) || card.part_name)}</span>
            {extra}
          </span>
        </span>
        <span className="text-ink-3">{time}</span>
        {late && <span className="sr-only">Misses the trucks.</span>}
      </div>
    </li>
  )
}

function GroupRow(p: Props & { g: Group }) {
  const { g } = p
  if (g.cards.length === 1) return <Row card={g.lead} {...p} />
  const open = p.expanded.has(g.key)
  const inGroup = g.cards.some((c) => c.id === p.selectedId)
  const toggle = (
    <button
      onClick={(e) => { e.stopPropagation(); p.onToggle(g.key) }}
      onKeyDown={(e) => e.stopPropagation()}
      aria-expanded={open}
      className="shrink-0 cursor-pointer text-ink-3 underline decoration-hair underline-offset-4 hover:text-ink"
    >
      {open ? 'hide' : `${g.cards.length - 1} more like this`}
    </button>
  )
  return (
    <>
      <Row card={g.lead} {...p} extra={<><span>·</span>{toggle}</>} selected={open ? p.selectedId === g.lead.id : inGroup} />
      {open && g.cards.slice(1).map((c) => {
        const label = sameIssueOn({ ...g, cards: [g.lead, c] }) ?? tidy(c.headline)
        const on = p.selectedId === c.id
        return (
          <li key={c.id}>
            <button
              id={`row-${c.id}`}
              onClick={() => p.onSelect(c.id)}
              aria-current={on ? 'true' : undefined}
              className={cn(rowCls, 'flex items-baseline justify-between gap-3 py-2 pl-[38px]', on && 'bg-soft')}
            >
              <span className={cn('truncate', on ? 'font-medium text-ink' : 'text-ink-2')}>{label}</span>
              {c.number != null && c.number > 0 && (
                <span className="shrink-0 text-ink-3">{fmtNum(c.number)}</span>
              )}
            </button>
          </li>
        )
      })}
    </>
  )
}

import { Check, ChevronRight, Database, FileText } from 'lucide-react'
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { EvidenceItem, Trail } from '@/components/EvidenceDrawer'
import { AnchorCrop, NUM_OR_ID, fileUrl, normTok, useAnchors, type Anchor } from '@/components/SourceAnchors'
import { VoiceCall } from '@/components/VoiceCall'
import { DONE_WORD, post, sentence, tidy, type Card, type Evidence, type State } from '@/lib/api'
import { languageOf, replyFacts, routineActionOf, routineOf, sameIssueOn, when, type Group } from '@/lib/decisions'
import {
  actionText, claimOf, costLine, costsMoney, docKind, forToday, headlineOf, recommendedIndex, shortName, summaryLine, type Claim,
} from '@/lib/today'
import { cn } from '@/lib/utils'
import { PaneHints } from './routines/PaneHints'
import { UndoAction } from './routines/Undo'

export interface Offer {
  /** Open cards left that look like the one just decided. */
  more: number
  onYes: () => void
  onNext: () => void
}

interface Props {
  card: Card
  state: State
  nowMs: number
  group?: Group | null
  /** Opened from the deep link (/d/<id>): whoever it is routed to can act on it here. */
  direct?: boolean
  /** Listen for a / Enter / Esc (the desktop pane). */
  keys?: boolean
  onChanged: () => void
  onDrawer: (card: Card, tab: 'evidence' | 'trail') => void
  ringing?: boolean
  onRingingDone?: () => void
  offer?: Offer | null
}

const first = (s?: string) => (!s ? '' : /\s[a-z]/.test(s) ? s : (s.split(' ').find((w) => !w.endsWith('.')) ?? s))
const typing = (t: EventTarget | null) =>
  t instanceof HTMLElement && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))
const lower = (t: string) => (t ? t[0].toLowerCase() + t.slice(1) : t)

// One decision in Plan: Today's decision (headline, the contradiction with tappable sources, the
// recommendation, one blue button), then the Plan-only parts as quiet folds below a hairline.
export function DecisionPane({
  card, state, nowMs, group, direct, keys, onChanged, onDrawer, ringing, onRingingDone, offer,
}: Props) {
  const [sel, setSel] = useState(() => recommendedIndex(card))
  const [text, setText] = useState(() => card.options[recommendedIndex(card)]?.draft ?? '')
  const [editing, setEditing] = useState(false)
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [confirm, setConfirm] = useState(false)
  // The source opened under the sentence, as on Today: closed until a citation is tapped.
  const [src, setSrc] = useState<number | null>(null)
  const [linesEl, setLinesEl] = useState<HTMLDivElement | null>(null)
  const anchors = useAnchors(card.id)

  const opt = card.options[sel]
  const other = card.routed_to_other || card.status === 'escalated'
  const closed = card.status !== 'open' && card.status !== 'escalated'
  const actionable = (!other || !!direct) && !closed && !!opt
  const who = first(card.approver) || 'the approver'
  const claim = claimOf(card)
  const today = !closed ? forToday(card, state, nowMs) : null
  const recommended = sel === recommendedIndex(card)
  const routine = closed ? routineOf(state, card.id) : null
  const undoId = routine ? routineActionOf(state, card.id) : null
  const facts = replyFacts(card)
  const same = group ? sameIssueOn(group) : null
  const late = card.level === 'red'
  const emails = !!opt && opt.channel === 'email' && /@/.test(opt.to ?? '')
  const money = !!opt && costsMoney(card, sel)
  const edited = editing && text.trim() !== (opt?.draft ?? '').trim()
  const shown = src

  async function act(fn: () => Promise<unknown>) {
    setBusy(true); setError('')
    try { await fn(); onChanged() } catch (e) {
      setError(`That did not go through: ${(e as Error).message}. Nothing was sent.`)
    } finally { setBusy(false); setConfirm(false) }
  }
  const approve = () =>
    act(() => post(`/api/cards/${encodeURIComponent(card.id)}/approve`, edited ? { option: sel, text } : { option: sel }))
  const escalate = () => act(() => post(`/api/cards/${encodeURIComponent(card.id)}/escalate`, { note }))
  const dismiss = () => act(() => post(`/api/cards/${encodeURIComponent(card.id)}/dismiss`))
  // An email or money is said out loud first: one more press sends it.
  const onApprove = () => (confirm ? void approve() : emails || money ? setConfirm(true) : void approve())
  const pick = (i: number) => { setSel(i); setText(card.options[i]?.draft ?? ''); setEditing(false); setConfirm(false) }

  // Keyboard: a asks, Enter approves, Esc cancels. Never while typing.
  const approveRef = useRef(approve)
  approveRef.current = approve
  useEffect(() => {
    if (!keys) return
    const onKey = (e: KeyboardEvent) => {
      if (typing(e.target) || e.metaKey || e.ctrlKey || e.altKey) return
      if (confirm && e.key === 'Enter') { e.preventDefault(); void approveRef.current() }
      else if (confirm && e.key === 'Escape') { e.preventDefault(); setConfirm(false) }
      else if (!confirm && e.key.toLowerCase() === 'a' && actionable && !busy) { e.preventDefault(); setConfirm(true) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [keys, confirm, actionable, busy])

  const decideBy = !closed && card.deadline
    ? new Date(card.deadline).getTime() <= nowMs ? 'decide now' : `decide by ${when(card.deadline, nowMs)}`
    : ''
  const meta = [card.supplier_name || card.part_name, decideBy].filter(Boolean).join(' · ') || 'Soony'

  return (
    <article className="pane-in" aria-label={headlineOf(card, state)}>
      <p className="t-small mb-4 text-ink-3">{meta}</p>
      <h1 className="t-big text-ink">{headlineOf(card, state)}</h1>
      {same && <p className="t-small mt-3 text-ink-3">Same issue on {same}.</p>}

      {/* where it stands */}
      {closed && (
        <p className="t-body mt-6 flex flex-wrap items-baseline gap-x-2 text-ink-2">
          <Check size={17} strokeWidth={1.75} className="translate-y-0.5 self-center text-ink" />
          <span className="text-ink">{DONE_WORD[card.status] ?? 'Done'}{card.ui?.at ? ` ${when(card.ui.at, nowMs)}` : ''}.</span>
          {routine && <span className="t-small dot-routine text-routine">By your routine {routine}</span>}
          {undoId && <UndoAction actionId={undoId} onUndone={onChanged} />}
        </p>
      )}
      {closed && offer && <AutomateOffer card={card} offer={offer} />}
      {other && (
        <p className="t-body mt-6 text-ink-2">
          <span className="text-ink">{card.status === 'escalated' ? `Waiting for ${who}.` : `With ${who}.`}</span>
          {card.reason && <> {sentence(card.reason)}</>}
        </p>
      )}

      <div className="mt-6 empty:hidden"><PaneHints card={card} onChanged={onChanged} /></div>

      {facts && (
        <p className="t-body mt-6 text-ink">
          {facts.text}{facts.late ? <span className="text-late">, after launch.</span> : '.'}
        </p>
      )}

      {/* the contradiction, with its sources */}
      <p className="t-body mt-6 text-ink-2">
        {claim ? (
          <ClaimLine claim={claim} late={late} open={shown} onOpen={(i) => setSrc(shown === i ? null : i)} />
        ) : (
          <Cited text={summaryLine(card)} anchors={anchors.items} open={shown} onOpen={(i) => setSrc(shown === i ? null : i)} />
        )}
      </p>
      {shown != null && card.evidence[shown] && (
        <Source card={card} ev={card.evidence[shown]} anchor={anchors.items?.[shown]?.[0]} ready={anchors.ready} onClose={() => setSrc(null)} />
      )}
      {today && (
        <p className="t-body mt-4 text-ink-2">For today: <span className="font-medium text-ink">{today.bold}</span>{today.rest}</p>
      )}

      {/* what to do */}
      {actionable && (
        <>
          <div className="mt-12">
            <p className="t-small mb-1.5 text-ink-3">{recommended ? 'We recommend' : 'Your choice'}</p>
            <p className="t-body text-ink">{actionText(card, sel)}</p>
            <p className="t-body text-ink-2">{costLine(card, sel)}{opt.effect ? ` ${sentence(opt.effect)}` : ''}</p>
          </div>

          {card.options.length > 1 && (
            <ul className="mt-5" aria-label="Other options">
              {card.options.map((_, i) =>
                i === sel ? null : (
                  <li key={i}>
                    <button
                      onClick={() => pick(i)}
                      className="t-body block w-full cursor-pointer py-1.5 text-left text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
                    >
                      <span className="text-ink-3">Or </span>{lower(actionText(card, i))}{' '}
                      <span className="t-small text-ink-3">{costLine(card, i)}</span>
                    </button>
                  </li>
                ),
              )}
            </ul>
          )}

          <div className="mt-8">
            {confirm && (
              <p className="t-small mb-3 text-ink-2" role="alert">
                {emails ? <>This email goes to <span className="text-ink">{opt.to}</span>{edited ? ' with your text' : ''}. </> : null}
                Approve: <span className="text-ink">{actionText(card, sel).replace(/\.$/, '')}</span> ({costLine(card, sel).replace(/\.$/, '')})
                {keys && <span className="text-ink-3"> · <kbd>Enter</kbd> confirms, <kbd>Esc</kbd> cancels</span>}
              </p>
            )}
            {error && <p className="t-small mb-3 text-late" role="alert">{error}</p>}
            <div className="flex flex-wrap items-center gap-6">
              <button
                onClick={onApprove}
                disabled={busy}
                className={cn(
                  't-body inline-flex h-12 cursor-pointer items-center justify-center rounded-xl px-7 font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:opacity-60',
                  ringing ? 'bg-soft text-ink hover:bg-hair' : 'bg-accent text-white shadow-[0_1px_2px_rgba(35,72,208,.25)] hover:bg-[#1d3db5]',
                )}
              >
                {busy ? 'Sending…' : confirm ? (emails ? 'Yes, send it' : 'Yes, approve') : edited ? 'Approve edited' : 'Approve'}
              </button>
              <div className={cn('t-body flex items-center gap-6', ringing && 'order-first w-full flex-col items-start gap-4 pb-2')}>
                <VoiceCall card={card} onChanged={onChanged} ringing={ringing} onRingingDone={onRingingDone} quiet linesEl={linesEl} />
                {confirm && <button onClick={() => setConfirm(false)} className="cursor-pointer text-ink-2 hover:text-ink">Cancel</button>}
              </div>
            </div>
          </div>
        </>
      )}
      <div ref={setLinesEl} />

      {!actionable && !closed && (
        <div className="t-body mt-8"><VoiceCall card={card} onChanged={onChanged} ringing={ringing} onRingingDone={onRingingDone} quiet linesEl={linesEl} /></div>
      )}

      {card.ui?.reply && (
        <section className="mt-12">
          <p className="t-small text-ink-3">
            Reply from {card.ui.reply_from || 'the supplier'}{card.ui.reply_at ? ` · ${when(card.ui.reply_at, nowMs)}` : ''}
          </p>
          <p className="t-body mt-1.5 text-ink">{card.ui.reply}</p>
          {card.ui.reply_text && (
            <details className="group mt-2">
              <summary className="t-small cursor-pointer list-none text-ink-3 hover:text-ink [&::-webkit-details-marker]:hidden">
                <span className="border-b border-hair">Original email</span>
              </summary>
              <pre className="t-small mt-2 whitespace-pre-wrap break-words font-sans text-ink-2">{card.ui.reply_text}</pre>
            </details>
          )}
        </section>
      )}

      {/* Plan only: everything behind it, folded */}
      <div className="mt-14 border-t border-hair">
        {card.evidence.length > 0 && (
          <Fold title="All evidence" n={card.evidence.length}>
            <div className="space-y-7">
              {claim && card.summary && <p className="t-body text-ink-2">{sentence(card.summary)}</p>}
              {card.evidence.map((e, i) => <EvidenceItem key={i} e={e} anchors={anchors.items?.[i]} ready={anchors.ready} />)}
              <button onClick={() => onDrawer(card, 'evidence')} className="t-small cursor-pointer text-ink-3 hover:text-ink">
                <span className="border-b border-hair">Open beside the list</span>
              </button>
            </div>
          </Fold>
        )}
        {card.trail.length > 0 && (
          <Fold title="How we know" n={card.trail.length}>
            <Trail card={card} />
          </Fold>
        )}
        {actionable && opt.draft && (
          <Fold title={emails ? 'Edit the email' : 'Edit the message'} onToggle={setEditing}>
            {emails && (
              <p className="t-small mb-2 text-ink-3">To {card.supplier_name ? `${shortName(card.supplier_name)} · ` : ''}{opt.to}</p>
            )}
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              rows={8}
              className="t-body w-full resize-y rounded-xl bg-soft p-4 leading-relaxed text-ink focus:outline-2 focus:outline-accent"
              aria-label="Edit the message"
            />
            <p className="t-small mt-2 text-ink-3">
              {edited ? 'Approve above sends your text.' : 'Change the text, then approve above.'}
              {edited && <button onClick={() => setText(opt.draft ?? '')} className="uline ml-2">Reset</button>}
            </p>
          </Fold>
        )}
        {actionable && (
          <Fold title={`Escalate to ${who}`}>
            <p className="t-small text-ink-3">They get this brief:</p>
            <p className="t-small mt-1 text-ink-2">{tidy(card.escalation_brief)}</p>
            <div className="mt-4 flex flex-wrap items-center gap-4">
              <input
                value={note}
                onChange={(e) => setNote(e.target.value)}
                placeholder="Add one line (optional)"
                className="t-small h-10 min-w-0 flex-1 rounded-lg bg-soft px-3 focus:outline-2 focus:outline-accent"
                aria-label={`Note for ${who}`}
              />
              <button disabled={busy} onClick={escalate} className="t-small cursor-pointer font-medium text-accent hover:underline disabled:opacity-60">
                Send to {who}
              </button>
            </div>
          </Fold>
        )}
        {actionable && (
          <p className="t-small border-b border-hair py-4 text-ink-3">
            Nothing to do?{' '}
            <button disabled={busy} onClick={dismiss} className="uline">Dismiss it</button>
          </p>
        )}
      </div>
    </article>
  )
}

function Fold({ title, n, children, onToggle }: { title: string; n?: number; children: ReactNode; onToggle?: (open: boolean) => void }) {
  return (
    <details className="group border-b border-hair" onToggle={(e) => onToggle?.((e.currentTarget as HTMLDetailsElement).open)}>
      <summary className="t-small flex cursor-pointer list-none items-center gap-2 py-4 text-ink-2 hover:text-ink focus-visible:outline-2 focus-visible:outline-accent [&::-webkit-details-marker]:hidden">
        <ChevronRight size={15} strokeWidth={1.75} className="text-ink-3 transition-transform group-open:rotate-90" />
        {title}{n != null && <span className="text-ink-3">· {n}</span>}
      </summary>
      <div className="fade pb-8 pl-[23px] pt-1">{children}</div>
    </details>
  )
}

/** After a decision by hand: offer to handle the next ones like it, in place. */
function AutomateOffer({ card, offer }: { card: Card; offer: Offer }) {
  const who = shortName(card.supplier_name)
  return (
    <section className="rise mt-10" aria-live="polite">
      <p className="t-body text-ink">
        {offer.more > 0
          ? `${offer.more} more like this${who ? ` from ${who}` : ''}. Handle them the same way?`
          : 'Handle the next one like this on its own?'}
      </p>
      <p className="t-small dot-routine mt-3 text-routine">You'll see a test run first. Anything that costs money still comes to you.</p>
      <div className="mt-6 flex items-center gap-6">
        <button
          onClick={offer.onYes}
          className="t-body inline-flex h-12 cursor-pointer items-center rounded-xl bg-accent px-7 font-medium text-white hover:bg-[#1d3db5] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
        >
          Show me how
        </button>
        <button onClick={offer.onNext} className="t-body cursor-pointer text-ink-2 hover:text-ink">Not now</button>
      </div>
    </section>
  )
}

// ---------------------------------------------------------------- the sentence and its sources

function ClaimLine({ claim, late, open, onOpen }: { claim: Claim; late: boolean; open: number | null; onOpen: (i: number) => void }) {
  return (
    <>
      {claim.pre}
      <button className="cite" aria-expanded={open === claim.sys.index} onClick={() => onOpen(claim.sys.index)}>
        {claim.sys.value}<Database aria-hidden="true" />
      </button>
      {claim.mid}
      <button className={cn('cite', late && 'late')} aria-expanded={open === claim.doc.index} onClick={() => onOpen(claim.doc.index)}>
        {claim.doc.value}<FileText aria-hidden="true" />
      </button>
      {claim.post}
    </>
  )
}

/** A sentence whose numbers, when found in a source, open that source. */
function Cited({ text, anchors, onOpen, open }: { text: string; anchors: Record<number, Anchor[]> | null; onOpen: (i: number) => void; open: number | null }) {
  if (!text) return null
  const flat = Object.entries(anchors ?? {}).flatMap(([i, as]) => as.map((a) => ({ i: Number(i), a })))
  const parts: ReactNode[] = []
  let last = 0
  for (const m of text.matchAll(NUM_OR_ID)) {
    const hit = flat.find((x) => x.a.matched.includes(normTok(m[0])))
    if (!hit || !/\d/.test(m[0])) continue
    parts.push(text.slice(last, m.index))
    parts.push(
      <button key={m.index} className="cite" aria-expanded={open === hit.i} onClick={() => onOpen(hit.i)}>{m[0]}</button>,
    )
    last = (m.index ?? 0) + m[0].length
  }
  parts.push(text.slice(last))
  return <>{parts}</>
}

const SYS = /system|sap|erp/i
const where = (a?: Anchor, ev?: Evidence) =>
  a ? (a.kind === 'table' || a.kind === 'text' ? `row ${(a.row ?? 0) + 1}` : `page ${a.page ?? 1}`) : ev?.page ? `page ${ev.page}` : ''

/** The source of one side, opened in place: the crop with the highlighter, then in English. */
function Source({ card, ev, anchor: a, ready, onClose }: { card: Card; ev: Evidence; anchor?: Anchor; ready: boolean; onClose: () => void }) {
  const isSys = SYS.test(ev.source ?? '')
  const head = [
    isSys ? (/\bSAP\b/.test(ev.source ?? '') ? 'SAP' : 'System') : card.supplier_name,
    [docKind(ev.source), where(a, ev)].filter(Boolean).join(', '),
    languageOf(ev.source, ev.language),
  ].filter(Boolean).join(' · ')
  const english = ev.translation ? ev.translation.split(' = ').pop() : null
  const original = a ? fileUrl(a) : ev.doc ? `/api/file?path=${encodeURIComponent(ev.doc)}${ev.page ? `#page=${ev.page}` : ''}` : null
  return (
    <section className="fade mt-5" aria-label="Source">
      <p className="t-small text-ink-3">{head}</p>
      <div className="mt-2 overflow-hidden rounded-xl bg-soft p-3">
        {a ? (
          <AnchorCrop key={a.doc} anchor={a} />
        ) : !ready ? (
          <p className="t-small p-2 text-ink-3">Finding it in the documents…</p>
        ) : (
          <p className="t-small whitespace-pre-wrap p-2 leading-[1.9] text-ink-2"><Marked text={tidy(ev.quote) || String(ev.value ?? '')} value={String(ev.value ?? '')} /></p>
        )}
      </div>
      {english && <p className="t-body mt-3 text-ink">{english}</p>}
      <p className="t-small mt-3 flex gap-5">
        {original && <a href={original} target="_blank" rel="noreferrer" className="text-accent hover:underline">Open original</a>}
        <button onClick={onClose} className="cursor-pointer text-ink-3 hover:text-ink">Close</button>
      </p>
    </section>
  )
}

/** The quote with the value's numbers highlighted (when no page or row was found). */
function Marked({ text, value }: { text: string; value: string }) {
  const nums = new Set((value.match(/\d[\d,.]*\d|\d/g) ?? []).map(normTok))
  const parts: ReactNode[] = []
  let last = 0
  for (const m of text.matchAll(/\d[\d,.]*\d|\d/g)) {
    if (!nums.has(normTok(m[0]))) continue
    parts.push(text.slice(last, m.index), <mark key={m.index} className="rounded-[3px] bg-mark px-1 font-medium text-[#111]">{m[0]}</mark>)
    last = (m.index ?? 0) + m[0].length
  }
  parts.push(text.slice(last))
  return <>{parts}</>
}

